// Input Parsing
const allItems = $input.all();

const qtoSummary = allItems.find(i => i.json._type === 'qto_summary');
const qtoComparisons = allItems.filter(i => i.json._type === 'qto_comparison');
const elements = allItems.filter(i => i.json._type === 'element');

const srccLookup = {};
if (qtoSummary?.json.srcc_results) {
  for (const s of qtoSummary.json.srcc_results) {
    srccLookup[s.QtoField] = s.SRCC;
  }
}

const qtoByGid = {};
for (const comp of qtoComparisons) {
  const gid = comp.json.GlobalId;
  if (!qtoByGid[gid]) qtoByGid[gid] = [];
  qtoByGid[gid].push(comp.json);
}

// Weights and Rules
const WEIGHTS = {
  completeness:  0.35,
  validity:      0.25,
  qto_coverage:  0.20,
  qto_agreement: 0.20,
};

const REQUIRED_PROPS = {
  IfcWall:                  ['IsExternal', 'LoadBearing'],
  IfcWallStandardCase:      ['IsExternal', 'LoadBearing'],
  IfcSlab:                  ['IsExternal', 'LoadBearing'],
  IfcSlabStandardCase:      ['IsExternal', 'LoadBearing'],
  IfcBeam:                  ['IsExternal', 'LoadBearing'],
  IfcColumn:                ['IsExternal', 'LoadBearing'],
  IfcRoof:                  ['IsExternal'],
  IfcDoor:                  ['IsExternal', 'FireRating'],
  IfcWindow:                ['IsExternal'],
  IfcSpace:                 ['IsExternal', 'GrossPlannedArea'],
  IfcChimney:               [],
  IfcFurniture:             [],
  IfcBuildingElementProxy:  [],
  IfcSpatialZone:           [],
  IfcZone:                  [],
};

const EXPECTED_QTO = {
  IfcWall:             ['NetVolume', 'Width', 'Length', 'NetSideArea'],
  IfcWallStandardCase: ['NetVolume', 'Width', 'Length', 'NetSideArea'],
  IfcSlab:             ['NetVolume', 'Depth', 'NetArea'],
  IfcSlabStandardCase: ['NetVolume', 'Depth', 'NetArea'],
  IfcBeam:             ['NetVolume', 'Length'],
  IfcColumn:           ['NetVolume', 'Length'],
  IfcRoof:             [],
  IfcSpace:            [],
};

// Scoring Function
function scoreElement(elem) {
  const type = elem.Category || elem.Type || '';
  const gid  = elem.GlobalId;

  // Completeness
  const required = REQUIRED_PROPS[type] || [];
  const missingProps = required.filter(prop =>
    !Object.keys(elem).some(k => k.includes(prop) && elem[k] != null && elem[k] !== '')
  );
  const completenessScore = required.length > 0
    ? (required.length - missingProps.length) / required.length : 1.0;

  // Validity
  const propKeys = Object.keys(elem).filter(k => k.startsWith('[Pset_'));
  const invalidProps = propKeys.filter(k => {
    const v = elem[k];
    return v === '' || v === null || v === undefined || v === "['UNSET']" || v === 'UNSET' || v === 'N/A';
  });
  const validityScore = propKeys.length > 0
    ? (propKeys.length - invalidProps.length) / propKeys.length : 1.0;

  // QTO Coverage
  const expectedQto = EXPECTED_QTO[type] || [];
  const missingQto = expectedQto.filter(qty =>
    !Object.keys(elem).some(k => k.includes(qty) && elem[k] != null && elem[k] !== '')
  );
  const qtoCoverageScore = expectedQto.length > 0
    ? (expectedQto.length - missingQto.length) / expectedQto.length : 1.0;

  // QTO Agreement
  const qtoComps = qtoByGid[gid] || [];
  const qtoAgreementScore = qtoComps.length > 0
    ? qtoComps.filter(c => c.Match === 'exact' || c.Match === 'negligible').length / qtoComps.length
    : 1.0;

  // Final BQI
  const bqi =
    WEIGHTS.completeness  * completenessScore  +
    WEIGHTS.validity      * validityScore      +
    WEIGHTS.qto_coverage  * qtoCoverageScore   +
    WEIGHTS.qto_agreement * qtoAgreementScore;

  const confidence = bqi >= 0.85 ? 'high' : bqi >= 0.60 ? 'medium' : 'low';

  const penalties = [];
  if (completenessScore  < 0.5) penalties.push('incomplete_properties');
  if (validityScore      < 0.5) penalties.push('invalid_values');
  if (qtoCoverageScore   < 0.5) penalties.push('missing_qto');
  if (qtoAgreementScore  < 0.5) penalties.push('qto_disagreement');
  if (!elem.Material || elem.Material === '') penalties.push('no_material');

  return {
    _type:          'bqi_scored',
    GlobalId:       gid,
    Name:           elem.Name || '',
    Category:       type,
    Material:       elem.Material || '',
    ObjectType:     elem.ObjectType || '',
    bqi_score:      Math.round(bqi * 1000) / 1000,
    bqi_confidence: confidence,
    score_completeness:  Math.round(completenessScore * 100) / 100,
    score_validity:      Math.round(validityScore * 100) / 100,
    score_qto_coverage:  Math.round(qtoCoverageScore * 100) / 100,
    score_qto_agreement: Math.round(qtoAgreementScore * 100) / 100,
    missing_properties: missingProps,
    invalid_properties: invalidProps,
    missing_qto:        missingQto,
    penalties,
    ...Object.fromEntries(Object.entries(elem).filter(([k]) => k.startsWith('[Qto_'))),
    ...Object.fromEntries(Object.entries(elem).filter(([k]) => k.startsWith('[Pset_'))),
  };
}

// Run and Output
const elementsToScore = (() => {
  const b = allItems.filter(i => i.json._type === 'element' && i.json.pipeline === 'B_ifcopenshell');
  return b.length > 0 ? b : allItems.filter(i => i.json._type === 'element' && i.json.pipeline === 'A_ddc');
})();

const output = [];
if (qtoSummary) output.push(qtoSummary);
for (const elem of elementsToScore) output.push({ json: scoreElement(elem.json) });

const scored = output.filter(i => i.json._type === 'bqi_scored');
const avgBqi = scored.length > 0
  ? scored.reduce((s, i) => s + i.json.bqi_score, 0) / scored.length : 0;

output.unshift({ json: {
  _type:                 'bqi_model_summary',
  model_bqi:             Math.round(avgBqi * 1000) / 1000,
  model_confidence:      avgBqi >= 0.85 ? 'high' : avgBqi >= 0.60 ? 'medium' : 'low',
  total_elements_scored: scored.length,
  distribution: {
    high:   scored.filter(i => i.json.bqi_confidence === 'high').length,
    medium: scored.filter(i => i.json.bqi_confidence === 'medium').length,
    low:    scored.filter(i => i.json.bqi_confidence === 'low').length,
  },
  weights_used: WEIGHTS,
}});

return output;

const EXPOSURE = {
  IfcRoof: 0.9, IfcChimney: 0.8, IfcPavement: 0.75, IfcRail: 0.7,
  IfcFooting: 0.65, IfcPile: 0.6,
  IfcWall: { base: 0.45, ext: 0.4 }, IfcWallStandardCase: { base: 0.45, ext: 0.4 },
  IfcSlab: { base: 0.45, ext: 0.3 }, IfcSlabStandardCase: { base: 0.45, ext: 0.3 },
  IfcColumn: { base: 0.45, ext: 0.3 }, IfcColumnStandardCase: { base: 0.45, ext: 0.3 },
  IfcBeam: { base: 0.35, ext: 0.2 }, IfcBeamStandardCase: { base: 0.35, ext: 0.2 },
  IfcDoor: { base: 0.35, ext: 0.3 }, IfcWindow: { base: 0.35, ext: 0.35 },
  IfcStair: { base: 0.3, ext: 0.2 }, IfcStairFlight: { base: 0.3, ext: 0.2 },
  IfcRamp: { base: 0.3, ext: 0.2 }, IfcRampFlight: { base: 0.3, ext: 0.2 },
  IfcCovering: { base: 0.25, ext: 0.2 }, IfcRailing: { base: 0.25, ext: 0.2 },
  IfcMember: 0.3, IfcPlate: 0.3,
  IfcReinforcingBar: 0.35, IfcReinforcingMesh: 0.35, IfcTendon: 0.3,
  IfcFurniture: 0.1, IfcFurnishingElement: 0.1, IfcSpace: 0.1,
};

const output = [];
for (const item of $input.all()) {
  if (item.json._type !== 'bqi_scored') { output.push(item); continue; }

  const type = item.json.Category || '';
  const spec = EXPOSURE[type];

  const isExternal = Object.entries(item.json)
    .filter(([k]) => k.includes('IsExternal'))
    .some(([, v]) => v === true || v === 'True' || String(v) === '1');

  let exposure;
  if (typeof spec === 'number') {
    exposure = spec;
  } else if (spec) {
    exposure = spec.base + (isExternal ? spec.ext : 0);
  } else {
    exposure = isExternal ? 0.25 : 0.15;
  }

  output.push({ json: {
    ...item.json,
    exposure_score: Math.round(Math.min(1, exposure) * 1000) / 1000,
    is_external: isExternal,
  }});
}
return output;

const SUSCEPTIBILITY = {
  IfcRoof: 0.8, IfcChimney: 0.7, IfcPavement: 0.7, IfcFooting: 0.65, IfcPile: 0.6,
  IfcRail: 0.6, IfcWall: 0.5, IfcWallStandardCase: 0.5,
  IfcSlab: 0.5, IfcSlabStandardCase: 0.5,
  IfcColumn: 0.45, IfcColumnStandardCase: 0.45,
  IfcBeam: 0.45, IfcBeamStandardCase: 0.45,
  IfcDoor: 0.4, IfcWindow: 0.4, IfcStair: 0.4, IfcStairFlight: 0.4,
  IfcCovering: 0.4, IfcMember: 0.35, IfcPlate: 0.35,
  IfcReinforcingBar: 0.35, IfcReinforcingMesh: 0.35, IfcTendon: 0.3,
  IfcRailing: 0.3, IfcRamp: 0.3, IfcRampFlight: 0.3,
  IfcFurniture: 0.15, IfcFurnishingElement: 0.15, IfcSpace: 0.1,
};

function materialMod(mat) {
  if (!mat) return 0;
  const m = mat.toLowerCase();
  if (m.includes('wood') || m.includes('timber')) return 0.15;
  if (m.includes('masonry') || m.includes('brick')) return 0.10;
  if (m.includes('steel') || m.includes('metal')) return 0.05;
  return 0;
}

function bqiMod(bqi) {
  if (bqi >= 0.85) return -0.05;
  if (bqi < 0.60)  return  0.10;
  return 0;
}

const output = [];
for (const item of $input.all()) {
  if (item.json.exposure_score === undefined) { output.push(item); continue; }

  const susc = SUSCEPTIBILITY[item.json.Category] ?? 0.3;
  const raw  = item.json.exposure_score * (susc + materialMod(item.json.Material))
               + bqiMod(item.json.bqi_score || 0);

  output.push({ json: {
    ...item.json,
    likelihood: Math.round(Math.min(1, Math.max(0, raw)) * 1000) / 1000,
    defect_susceptibility: susc,
  }});
}
return output;

const CRITICALITY = {
  IfcColumn: 1.0, IfcColumnStandardCase: 1.0,
  IfcFooting: 1.0, IfcPile: 1.0,
  IfcBeam: 0.9, IfcBeamStandardCase: 0.9,
  IfcSlab: 0.9, IfcSlabStandardCase: 0.9,
  IfcWall: 0.8, IfcWallStandardCase: 0.8, IfcRoof: 0.8, IfcRail: 0.8,
  IfcTendon: 0.75, IfcReinforcingBar: 0.7, IfcReinforcingMesh: 0.65,
  IfcStair: 0.7, IfcStairFlight: 0.7, IfcPavement: 0.65, IfcChimney: 0.6,
  IfcMember: 0.6, IfcRamp: 0.55, IfcRampFlight: 0.55, IfcPlate: 0.5,
  IfcCovering: 0.4, IfcRailing: 0.4, IfcDoor: 0.35, IfcWindow: 0.35,
  IfcFurniture: 0.1, IfcFurnishingElement: 0.1, IfcSpace: 0.2,
};

function qtoExtent(elem) {
  const keys = Object.keys(elem);
  for (const kw of ['NetVolume','GrossVolume','NetArea','GrossArea','NetSideArea',
                    'NetFloorArea','GrossPlannedArea','Length','Depth','Width']) {
    const k = keys.find(x => x.includes(kw));
    if (k && elem[k]) return parseFloat(elem[k]) || 0;
  }
  return 0;
}

const scorable = $input.all().filter(i => i.json.likelihood !== undefined);
const others   = $input.all().filter(i => i.json.likelihood === undefined);
const maxExt   = Math.max(1, ...scorable.map(i => qtoExtent(i.json)));

const output = [];
for (const item of others) output.push(item);

for (const item of scorable) {
  const crit  = CRITICALITY[item.json.Category] ?? 0.3;
  const ext   = qtoExtent(item.json);
  const normE = ext > 0 ? Math.min(1, ext / maxExt) : 0.5;
  const cons  = Math.min(1, crit * (0.7 + 0.3 * normE));

  output.push({ json: {
    ...item.json,
    consequence: Math.round(cons * 1000) / 1000,
    element_criticality: crit,
    qto_extent: ext,
  }});
}
return output;

const CONF_MULT = { high: 1.0, medium: 1.10, low: 1.25 };

const output = [];
for (const item of $input.all()) {
  if (item.json.consequence === undefined) { output.push(item); continue; }

  const L    = item.json.likelihood  || 0;
  const C    = item.json.consequence || 0;
  const mult = CONF_MULT[item.json.bqi_confidence] ?? 1.25;

  output.push({ json: {
    ...item.json,
    risk_score:       Math.round(Math.min(1, L * C * mult) * 1000) / 1000,
    risk_multiplier:  mult,
    _type:            'risk_element',
  }});
}
return output;

const all       = $input.all();
const others    = all.filter(i => i.json._type !== 'risk_element');
const riskItems = all.filter(i => i.json._type === 'risk_element');

riskItems.sort((a, b) => (b.json.risk_score || 0) - (a.json.risk_score || 0));

const scores = [...riskItems].map(i => i.json.risk_score || 0).sort((a, b) => a - b);
const n      = scores.length;
const HIGH_T = n > 0 ? Math.max(scores[Math.floor(n * 0.75)] ?? 0, 0.40) : 0.40;
const LOW_T  = n > 0 ? Math.max(scores[Math.floor(n * 0.25)] ?? 0, 0.15) : 0.15;

const labeled = riskItems.map((item, idx) => {
  const s     = item.json.risk_score || 0;
  const label = s >= HIGH_T ? 'High' : s >= LOW_T ? 'Medium' : 'Low';
  return { json: {
    ...item.json,
    risk_label:      label,
    risk_rank:       idx + 1,
    risk_percentile: Math.round((1 - idx / Math.max(n, 1)) * 100),
    zone:            item.json.is_external ? 'Exterior' : 'Interior',
    location_tag:    item.json.is_external ? 'Exterior' : 'Interior',
  }};
});

return [...others, ...labeled];

const all = $input.all();

// Pass all typed items through; add zone/location_tag for HTML report
return all.map(item => {
  if (item.json._type !== 'risk_element') return item;
  return { json: {
    ...item.json,
    zone:         item.json.zone         || (item.json.is_external ? 'Exterior' : 'Interior'),
    location_tag: item.json.location_tag || (item.json.is_external ? 'Exterior' : 'Interior'),
  }};
});

const allItems = $input.all();

let projectFilePath = '';
try {
  projectFilePath = $node['S1: Setup paths'].json.project_file || '';
} catch(e) {
  projectFilePath = 'Unknown Project';
}
const projectFileName = projectFilePath.split('\\').pop().split('/').pop().replace(/\.[^/.]+$/, '');

const modelSummary  = allItems.find(i => i.json._type === 'bqi_model_summary') || { json: {} };
const riskElements  = allItems.filter(i => i.json._type === 'risk_element');
const qtoSummary    = allItems.find(i => i.json._type === 'qto_summary') || { json: {} };

const modelBQI        = +(modelSummary.json.model_bqi   || 0).toFixed(3);
const modelConf       = modelSummary.json.model_confidence || 'low';
const totalScored     = modelSummary.json.total_elements_scored || allItems.length;
const dist            = modelSummary.json.distribution || { high: 0, medium: 0, low: 0 };
const weights         = modelSummary.json.weights_used || { completeness: 0.35, validity: 0.25, qto_coverage: 0.20, qto_agreement: 0.20 };

const highRisk   = riskElements.filter(i => i.json.risk_label === 'High').length   || dist.high   || 0;
const medRisk    = riskElements.filter(i => i.json.risk_label === 'Medium').length || dist.medium || 0;
const lowRisk    = riskElements.filter(i => i.json.risk_label === 'Low').length    || dist.low    || 0;
const top10      = riskElements
  .sort((a,b) => (b.json.risk_score||0) - (a.json.risk_score||0))
  .slice(0, 10);

const srccResults = qtoSummary.json.srcc_results || [];
const avgSRCC     = srccResults.length
  ? (srccResults.reduce((s,r) => s + (r.SRCC||0), 0) / srccResults.length).toFixed(3)
  : 'N/A';

function confColor(conf) {
  if (conf === 'high')   return '#009a44';
  if (conf === 'medium') return '#ffa726';
  return '#dc3545';
}
function riskColor(label) {
  if (label === 'High')   return '#dc3545';
  if (label === 'Medium') return '#ffa726';
  return '#66bb6a';
}
function bqiBar(score) {
  const pct = Math.round((score||0) * 100);
  const col = score >= 0.7 ? '#009a44' : score >= 0.4 ? '#ffa726' : '#dc3545';
  return `<div style="background:#e0e0e0;height:6px;border-radius:3px;width:80px;display:inline-block;vertical-align:middle;margin-left:8px"><div style="height:100%;width:${pct}%;background:${col};border-radius:3px"></div></div>`;
}

const distData    = JSON.stringify([highRisk, medRisk, lowRisk]);
const bqiWeights  = JSON.stringify(Object.entries(weights).map(([k,v]) => ({ label: k.replace('_',' '), value: +(v*100).toFixed(0) })));
const srccChartData = JSON.stringify(srccResults.slice(0,8).map(r => ({ field: (r.QtoField||'').replace('[Qto_','').replace(']',''), srcc: +(r.SRCC||0).toFixed(3) })));
const top10Data   = JSON.stringify(top10.map(i => ({ id: (i.json.GlobalId||'').slice(0,8), score: +(i.json.risk_score||0).toFixed(3), bqi: +(i.json.bqi_score||0).toFixed(3), label: i.json.risk_label||'Low', type: i.json.Category||i.json._type||'' })));

const riskRows = top10.map((item, idx) => {
  const d = item.json;
  const label = d.risk_label || 'Low';
  return `<tr>
    <td>${idx+1}</td>
    <td style="font-family:monospace;font-size:11px">${(d.GlobalId||'—').slice(0,16)}</td>
    <td>${d.Category || d.ifc_type || '—'}</td>
    <td>${(d.zone || d.location_tag || '—')}</td>
    <td>${(+(d.bqi_score||0)).toFixed(2)} ${bqiBar(d.bqi_score)}</td>
    <td>${d.bqi_confidence || '—'}</td>
    <td>${(+(d.likelihood||0)).toFixed(2)}</td>
    <td>${(+(d.consequence||0)).toFixed(2)}</td>
    <td><strong>${(+(d.risk_score||0)).toFixed(3)}</strong></td>
    <td><span style="display:inline-block;padding:2px 8px;background:${riskColor(label)};color:white;font-size:11px;font-weight:600;border-radius:2px">${label.toUpperCase()}</span></td>
  </tr>`;
}).join('') || `<tr><td colspan="10" style="text-align:center;color:#999;padding:20px">Risk screening stubs (R1–R5) not yet implemented — placeholder data</td></tr>`;

const weightRows = Object.entries(weights).map(([k,v]) =>
  `<tr><td>${k.replace(/_/g,' ')}</td><td>${(v*100).toFixed(0)}%</td><td>${bqiBar(v)}</td></tr>`
).join('');

const html = `<!DOCTYPE html>
